"""Modality availability probing.

At ``clawarena-team run/resume`` startup, send a minimal request for each declared
non-text modality in main + the pool; if the provider returns a 4xx ("unsupported" /
format rejection), the modality is treated as unavailable and stripped from the
effective set.

Design points:
- a single request's ``max_tokens`` is tiny (default 4), so probing cost is negligible;
- any non-200/2xx is uniformly treated as the modality being unavailable, without
  distinguishing the specific error code;
- text is always treated as available (no request is sent);
- the probe assets are a 1×1 PNG / short silent WAV / short black-screen MP4, inlined
  as base64, requiring no file system.
"""
from __future__ import annotations

import asyncio
import base64
import json
import logging
from dataclasses import dataclass
from typing import Any

import httpx

from ..types import ModelConfig

log = logging.getLogger(__name__)


# ---------------------------------------------------------------------------
# Assets: tiny valid binaries, inlined as base64
# ---------------------------------------------------------------------------

# A 32×32 gray PNG (~98B). 1×1 is rejected by some clouds ("unsupported image"), so use 32×32.
_PNG_B64 = (
    "iVBORw0KGgoAAAANSUhEUgAAACAAAAAgCAIAAAD8GO2jAAAAKUlEQVR4nO3NMQEAAAjDMED5pGMCvlRA00nqs3m9AwAAAAAAAAAAgMMWvj0BwDVKG0sAAAAASUVORK5CYII="
)

# RIFF/WAV: 16000Hz mono 16-bit, 0.5s silence (~16KB). A degenerate 1-sample input would
# make gemma-4 omni's audio conv encoder **fatally crash the entire vLLM engine** because
# the mel frame count < kernel (3×3) (RuntimeError: Kernel size can't be greater than
# actual input size); hence it must be long enough.
_WAV_B64 = (
    ""
)

# A 64×64 gray mp4v, 4 frames (generated by opencv VideoWriter, ~980B). The earlier 16×16
# was rejected by Qwen3VLProcessor as "patch size too small"; changed to 64×64 to meet the
# minimum patch requirement of mainstream VL processors (28×28 patches × merge=2).
_MP4_B64 = (
    ""
)

_ASSETS: dict[str, tuple[str, str]] = {
    "image": ("image/png", _PNG_B64),
    "audio": ("audio/wav", _WAV_B64),
    "video": ("video/mp4", _MP4_B64),
}


# ---------------------------------------------------------------------------
# Build request content
# ---------------------------------------------------------------------------


def _content_part(modality: str) -> dict[str, Any]:
    mime, b64 = _ASSETS[modality]
    if modality == "image":
        return {"type": "image_url", "image_url": {"url": f"data:{mime};base64,{b64}"}}
    if modality == "audio":
        return {"type": "input_audio", "input_audio": {"data": b64, "format": "wav"}}
    if modality == "video":
        return {"type": "video_url", "video_url": {"url": f"data:{mime};base64,{b64}"}}
    raise ValueError(f"unknown modality: {modality!r}")


def _probe_messages(modality: str) -> list[dict[str, Any]]:
    return [
        {
            "role": "user",
            "content": [
                _content_part(modality),
                {"type": "text", "text": "ping"},
            ],
        }
    ]


# ---------------------------------------------------------------------------
# Probe body
# ---------------------------------------------------------------------------


@dataclass
class ProbeOutcome:
    modality: str
    ok: bool
    detail: str = ""

    def __str__(self) -> str:  # pragma: no cover - logging only
        verdict = "ok" if self.ok else "fail"
        return f"{self.modality}={verdict}" + (f" ({self.detail})" if self.detail else "")


async def _probe_one(
    config: ModelConfig,
    modality: str,
    *,
    timeout_sec: float,
    max_tokens: int,
) -> ProbeOutcome:
    if modality == "text":
        return ProbeOutcome(modality, True)
    if modality not in _ASSETS:
        return ProbeOutcome(modality, False, f"unknown modality {modality!r}")

    url = (config.api_base or "https://api.openai.com/v1").rstrip("/") + "/chat/completions"
    headers = {"Content-Type": "application/json"}
    if config.api_key:
        headers["Authorization"] = f"Bearer {config.api_key}"

    payload = {
        "model": config.model_id,
        "messages": _probe_messages(modality),
        "max_completion_tokens": max_tokens,
    }

    try:
        async with httpx.AsyncClient(timeout=httpx.Timeout(timeout_sec)) as client:
            resp = await client.post(url, json=payload, headers=headers)
    except httpx.HTTPError as e:
        return ProbeOutcome(modality, False, f"transport error: {e}")

    if resp.status_code // 100 == 2:
        return ProbeOutcome(modality, True)

    snippet = resp.text[:200].replace("\n", " ")
    return ProbeOutcome(modality, False, f"HTTP {resp.status_code}: {snippet}")


async def probe_model(
    config: ModelConfig,
    declared: list[str],
    *,
    timeout_sec: float = 20.0,
    max_tokens: int = 4,
) -> list[ProbeOutcome]:
    """Concurrently probe multiple declared modalities of the same model.

    Returns a list of :class:`ProbeOutcome` aligned with the order of ``declared``.
    """
    return await asyncio.gather(
        *[
            _probe_one(config, m, timeout_sec=timeout_sec, max_tokens=max_tokens)
            for m in declared
        ]
    )


__all__ = ["ProbeOutcome", "probe_model"]
